'use client';
import { type ReactNode, useRef, useState } from 'react';
import { motion, useInView, type Variant, type Transition, type UseInViewOptions } from 'motion/react';

export type InViewProps = {
  children: ReactNode;
  variants?: {
    hidden: Variant;
    visible: Variant;
  };
  transition?: Transition;
  viewOptions?: UseInViewOptions;
  as?: React.ElementType;
  once?: boolean
};

const defaultVariants = {
  hidden: { opacity: 0 },
  visible: { opacity: 1 },
};

export function InView({
  children,
  variants = defaultVariants,
  transition,
  viewOptions,
  as = 'div',
  once
}: InViewProps) {
  const ref = useRef(null);
  const isInView = useInView(ref, viewOptions);

  const [isViewed, setIsViewed] = useState(false)

  const MotionComponent = motion[as as keyof typeof motion] as typeof as;

  return (
    <MotionComponent
      ref={ref}
      initial='hidden'
      onAnimationComplete={() => {
        if (once) setIsViewed(true)
      }}
      animate={(isInView || isViewed) ? "visible" : "hidden"}

      variants={variants}
      transition={transition}
    >
      {children}
    </MotionComponent>
  );
}

import * as React from "react"
import { motion, useReducedMotion } from "motion/react"
import { InView } from "@/components/primitives/in-view"
import { SectionHead, SectionShell } from "@/components/primitives/handcraft"
import { cn } from "@/lib/utils"

// The layer components — head band, meta chips, text sections (repeat), base.
import { JobHead } from "./layers/JobHead"
import { JobMeta } from "./layers/JobMeta"
import { JobSection } from "./layers/JobSection"
import { JobBase } from "./layers/JobBase"

// ═══ JOB         Give the role a page worth working at.
// ═══ EMOTION     "I could see myself here" — concrete, honest, paid.
// ═══ SIGNATURE   The sections are the fillings: About / You'll / We offer
//                 slide in one per beat, each a component you can reorder or
//                 drop. Salary sits in the head band — nothing hidden.

export type StackJobProps = {
  eyebrow?: string
  title?: React.ReactNode
  subtitle?: React.ReactNode
  head?: { title: string; salary?: string; team?: string }
  meta?: { chips?: string[] }
  sections?: { heading: string; body: React.ReactNode }[]
  cta?: string
  deadline?: string
  caption?: string
  tone?: "paper" | "ink"
  className?: string
}

export function StackJob({
  eyebrow = "STACK · JOB",
  title = "A role, told in layers.",
  subtitle = "Title band, meta chips, text sections and apply base are separate components — sections repeat like fillings, so the posting reads like you write, not like a template.",
  head = { title: "Front of house — the calm kind", salary: "42 000 – 51 000 kr / month", team: "The Floor Team" },
  meta = { chips: ["Jönköping", "Hybrid · 2 days remote", "Full time"] },
  sections = [
    {
      heading: "About the role",
      body: "You are the first face and the last handshake. You run the board, greet the walk-ins, and keep chair three on time without ever sounding like a clock.",
    },
    {
      heading: "You'll fit if",
      body: "You have two years in a busy salon, spa or shop floor. You'd rather fix the double-booking than explain it. You write like a human.",
    },
    {
      heading: "We offer",
      body: "A board that respects your lunch, a team that covers honestly, payroll on the 25th sharp — and a training budget you don't have to beg for.",
    },
  ],
  cta = "Apply for this role",
  deadline = "Applies by Oct 12",
  caption = "FOUR LAYER COMPONENTS · REPEATABLE SECTIONS",
  tone = "paper",
  className,
}: StackJobProps) {
  const ink = tone === "ink"
  const reduce = useReducedMotion()

  return (
    <SectionShell tone={tone} width={920} rule="bottom" className={className}>
      <InView
        once
        variants={{ hidden: { opacity: 0, y: 14 }, visible: { opacity: 1, y: 0 } }}
        transition={{ duration: 0.8, ease: [0.16, 1, 0.3, 1] }}
      >
        <SectionHead eyebrow={eyebrow} title={title} subtitle={subtitle} tone={tone} />
      </InView>

      <InView
        once
        variants={{ hidden: { opacity: 0, y: 24 }, visible: { opacity: 1, y: 0 } }}
        transition={{ duration: 0.9, ease: [0.16, 1, 0.3, 1], delay: 0.1 }}
      >
        <figure className="mt-10">
          <div className="mx-auto max-w-[560px]">
            <div
              className={cn(
                "overflow-hidden rounded-[18px] border bg-card shadow-[0_26px_56px_-30px_hsl(var(--foreground)/0.45)]",
                ink ? "border-background/15" : "border-border",
              )}
            >
              <JobHead title={head.title} salary={head.salary} team={head.team} />
              <JobMeta chips={meta.chips} />

              <div>
                {sections.map((section, i) => (
                  <motion.div
                    key={section.heading}
                    initial={reduce ? { opacity: 0 } : { opacity: 0, x: -16 }}
                    whileInView={{ opacity: 1, x: 0 }}
                    viewport={{ once: true }}
                    transition={{ duration: 0.45, ease: [0.16, 1, 0.3, 1], delay: 0.25 + i * 0.09 }}
                  >
                    <JobSection heading={section.heading}>{section.body}</JobSection>
                  </motion.div>
                ))}
              </div>

              <motion.div
                initial={reduce ? { opacity: 0 } : { opacity: 0, y: 12 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true }}
                transition={{ duration: 0.5, ease: [0.16, 1, 0.3, 1], delay: 0.55 }}
              >
                <JobBase cta={cta} deadline={deadline} />
              </motion.div>
            </div>
          </div>

          {caption && (
            <figcaption
              className={cn(
                "mx-auto mt-8 flex max-w-[560px] items-center justify-between border-t pt-3 font-mono text-[10px] font-bold uppercase tracking-[0.3em]",
                ink ? "border-background/15 text-background/55" : "border-border text-muted-foreground",
              )}
            >
              <span>{caption}</span>
              <span aria-hidden>●</span>
            </figcaption>
          )}
        </figure>
      </InView>
    </SectionShell>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"

// ── JOB BASE — the bottom bun. Apply CTA + applies-by note. ─────────────────

export type JobBaseProps = {
  cta?: string
  onApply?: () => void
  deadline?: string
  className?: string
}

export function JobBase({ cta = "Apply for this role", onApply, deadline = "Applies by Oct 12", className }: JobBaseProps) {
  return (
    <div className={cn("flex items-center gap-3 rounded-b-[16px] border-t border-border/60 bg-muted/40 px-5 py-4", className)}>
      <button
        type="button"
        onClick={onApply}
        className="h-10 rounded-full bg-foreground px-5 text-[11px] font-black uppercase tracking-[0.14em] text-background transition-transform hover:-translate-y-0.5 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
      >
        {cta}
      </button>
      <span className="ml-auto font-mono text-[9px] font-bold uppercase tracking-[0.18em] text-muted-foreground">{deadline}</span>
    </div>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"

// ── JOB HEAD — the upper bun. Title + salary band. ──────────────────────────

export type JobHeadProps = {
  title: string
  salary?: string
  team?: string
  className?: string
}

export function JobHead({ title, salary = "42 000 – 51 000 kr / month", team = "The Floor Team", className }: JobHeadProps) {
  return (
    <div className={cn("rounded-t-[16px] bg-foreground px-5 py-4 text-background", className)}>
      <p className="font-mono text-[9px] font-bold uppercase tracking-[0.24em] opacity-60">{team}</p>
      <h3 className="mt-1 font-display text-[19px] font-extrabold tracking-tight">{title}</h3>
      <p className="mt-1.5 inline-block rounded-full border border-background/25 px-2.5 py-0.5 font-mono text-[10px] font-bold tabular-nums">
        {salary}
      </p>
    </div>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"

// ── JOB META — the chips band. Location / shape / pace. ─────────────────────

export type JobMetaProps = {
  chips?: string[]
  className?: string
}

export function JobMeta({ chips = ["Jönköping", "Hybrid · 2 days remote", "Full time"], className }: JobMetaProps) {
  return (
    <div className={cn("flex flex-wrap gap-2 border-b border-border/60 px-5 py-3.5", className)}>
      {chips.map((c) => (
        <span key={c} className="rounded-full border border-border bg-muted/50 px-3 py-1 font-mono text-[10px] font-bold uppercase tracking-[0.12em] text-muted-foreground">
          {c}
        </span>
      ))}
    </div>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"

// ── JOB SECTION — one titled text block. The filling: repeat per topic. ─────

export type JobSectionProps = {
  heading: string
  children: React.ReactNode
  className?: string
}

export function JobSection({ heading, children, className }: JobSectionProps) {
  return (
    <section className={cn("border-t border-border/50 px-5 py-4 first:border-t-0", className)}>
      <h4 className="font-mono text-[10px] font-black uppercase tracking-[0.22em] text-primary">{heading}</h4>
      <div className="mt-2 space-y-2 text-[13px] font-medium leading-relaxed text-muted-foreground">{children}</div>
    </section>
  )
}
